import type { NextApiRequest, NextApiResponse } from 'next'
import crypto from 'crypto'

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method not allowed' })
  }

  // NowPayments sends IPN signature in headers
  const signature = req.headers['x-nowpayments-sig'] as string
  const body = JSON.stringify(req.body)

  // Verify the IPN signature
  // NowPayments uses HMAC SHA512 with your IPN secret key
  const ipnKey = process.env.NOWPAYMENTS_IPN_KEY!
  const expectedSignature = crypto
    .createHmac('sha512', ipnKey)
    .update(body)
    .digest('hex')

  if (signature !== expectedSignature) {
    console.error('Invalid NowPayments IPN signature')
    return res.status(401).json({ error: 'Invalid signature' })
  }

  const { payment_status, order_id, pay_amount, pay_currency, actually_paid } = req.body

  try {
    switch (payment_status) {
      case 'waiting':
        console.log(`Payment waiting: ${order_id}`)
        // Update order status to 'pending'
        break

      case 'confirming':
        console.log(`Payment confirming: ${order_id}`)
        // Update order status to 'confirming'
        break

      case 'confirmed':
      case 'finished':
        console.log(`Payment confirmed: ${order_id} - ${pay_amount} ${pay_currency}`)
        // Update order to 'paid'
        // Send download link to customer
        // Trigger digital product delivery
        break

      case 'failed':
      case 'expired':
        console.log(`Payment failed: ${order_id}`)
        // Update order to 'failed'
        // Notify customer
        break

      case 'refunded':
        console.log(`Payment refunded: ${order_id}`)
        // Update order to 'refunded'
        // Revoke access if needed
        break
    }

    // Always return 200 to acknowledge receipt
    res.status(200).json({ received: true })
  } catch (error) {
    console.error('IPN processing error:', error)
    res.status(500).json({ error: 'Processing failed' })
  }
}
```

**Setup steps:**
1. Get your IPN key from NowPayments dashboard → Account Settings → IPN
2. Set NOWPAYMENTS_IPN_KEY in your .env
3. Set the webhook URL in NowPayments: https://yourdomain.com/api/webhooks/nowpayments
4. Deploy and test with a small payment

Here's a TypeScript price formatter for NGN/USD:

```typescript
/**
 * Format prices for Nigerian and international display
 * Supports NGN, USD, and dual-currency formatting
 */

class PriceFormatter {
  private exchangeRate: number

  constructor(exchangeRate: number = 1500) {
    // Default rate: 1 USD = ₦1500 (update regularly)
    this.exchangeRate = exchangeRate
  }

  setRate(rate: number) {
    this.exchangeRate = rate
  }

  formatNGN(amount: number): string {
    return `₦${amount.toLocaleString('en-NG', {
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    })}`
  }

  formatUSD(amount: number): string {
    return `$${amount.toLocaleString('en-US', {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    })}`
  }

  ngnToUSD(ngn: number): string {
    return this.formatUSD(ngn / this.exchangeRate)
  }

  usdToNGN(usd: number): string {
    return this.formatNGN(usd * this.exchangeRate)
  }

  dual(ngn: number): string {
    const usd = ngn / this.exchangeRate
    return `${this.formatNGN(ngn)} (${this.formatUSD(usd)})`
  }

  // For pay-what-you-want or tiered pricing
  formatTier(low: number, high: number, currency: 'NGN' | 'USD' = 'NGN'): string {
    if (currency === 'NGN') {
      return `${this.formatNGN(low)} - ${this.formatNGN(high)}`
    }
    return `${this.formatUSD(low)} - ${this.formatUSD(high)}`
  }
}

// Usage
const price = new PriceFormatter(1500)

console.log(price.formatNGN(25000))      // ₦25,000
console.log(price.formatUSD(16.67))      // $16.67
console.log(price.ngnToUSD(25000))       // $16.67
console.log(price.usdToNGN(100))         // ₦150,000
console.log(price.dual(25000))           // ₦25,000 ($16.67)
console.log(price.formatTier(15000, 50000)) // ₦15,000 - ₦50,000
```

Update the exchange rate regularly. For real-time rates, fetch from an API like exchangerate-api.com.

